SELECT COUNT(*) AS accused_named
FROM Accused
WHERE CaseMasterID = :case_id;

SELECT COUNT(*) AS unused_sections
FROM Section s
WHERE NOT EXISTS (
  SELECT 1 FROM ActSectionAssociation asa WHERE asa.SectionID = s.SectionID
);

SELECT MIN(CrimeRegisteredDate) AS earliest,
       MAX(CrimeRegisteredDate) AS latest
FROM CaseMaster;

SELECT COUNT(*) > 0 AS arrested
FROM ArrestSurrender
WHERE AccusedMasterID = :accused_id;

SELECT AVG(julianday(ars.ArrestDate) - julianday(cm.CrimeRegisteredDate)) AS avg_days
FROM ArrestSurrender ars
JOIN CaseMaster cm ON cm.CaseMasterID = ars.CaseMasterID;

SELECT ArrestType, COUNT(*) AS n
FROM ArrestSurrender
GROUP BY ArrestType;

SELECT AccusedMasterID, CaseMasterID, AccusedName, AgeYear
FROM Accused
WHERE AccusedName = :name;

SELECT COUNT(DISTINCT AccusedName) AS distinct_names,
       COUNT(*) AS rows_held
FROM Accused;

SELECT COUNT(*) AS complainant_rows,
       COUNT(DISTINCT rc.ResolvedIdentityID) AS distinct_people
FROM resolved_complainant rc;

SELECT COUNT(DISTINCT v.CaseMasterID) AS cases_with_victim,
       (SELECT COUNT(*) FROM CaseMaster) AS all_cases
FROM Victim v;

SELECT CrimeNo, CaseStatus
FROM CaseMaster
WHERE CaseMasterID = :case_id;

SELECT COUNT(*) AS b_reports
FROM CaseMaster
WHERE CaseStatus = 'B report';
